export function samePlayWindow(s,time,cutoff){
 if(cutoff>time)return false;
 const key=t=>events(s).filter(e=>e.end<=t).at(-1)?.id||'waiting';
 return key(time)===key(cutoff);
}
export function analyzePlay(s,cutoff=0,language='en'){
 const t=Math.max(0,Math.min(s.duration,Number(cutoff)||0)),c=words[language]||words.en;
 const seen=events(s).filter(e=>e.end<=t),regain=seen.find(e=>e.outcome==='intercepted'||e.type==='tackle');
 const passes=seen.filter(e=>e.type==='pass'&&e.team==='harbor'&&e.outcome==='complete'&&(!regain||e.t>=regain.end));
 const shot=seen.find(e=>e.type==='shot'&&(!regain||e.t>=regain.end));
 const forwardGain=passes.length?passes.reduce((sum,e)=>sum+e.endPosition[0]-e.start[0],0):null;
 const interval=regain&&shot?shot.t-regain.end:null,elapsed=regain?Math.max(0,(shot?.t??t)-regain.end):null;
 const record={id:`${s.id}-analysis-${t.toFixed(1)}`,record_type:'derived_analysis',second:t,source:'synthetic-events-and-tracking',event_ids:seen.map(e=>e.id)};
 let pressure=null;
 // Ali receives at 5s and releases at 7s; do not label him the ball carrier before receipt.
 if(s.id==='press'&&t>=5){const end=Math.min(t,7),from=distance(position(s,8,5),position(s,106,5)),to=distance(position(s,8,end),position(s,106,end));pressure={start:5,end,from,to,closed:from-to,samples:[{second:5,presser:position(s,8,5),carrier:position(s,106,5)},{second:end,presser:position(s,8,end),carrier:position(s,106,end)}]};}
 Object.assign(record,{forward_pass_gain_m:forwardGain,completed_passes:passes.length,regain_to_shot_s:interval,pressure});
 const n=v=>new Intl.NumberFormat(language,{maximumFractionDigits:1}).format(v);
 const calculations=[{id:'gain',label:c.gain,value:forwardGain===null?'—':n(forwardGain)+' m',text:forwardGain===null?c.noPass:({en:`${passes.length} completed ${passes.length===1?'pass moves':'passes move'} the ball ${n(forwardGain)} m toward goal, counting each pass’s end x minus start x. Carries are excluded.`,es:`${passes.length} pases completos avanzan ${n(forwardGain)} m hacia la portería, sumando x final menos x inicial. No incluye conducciones.`,pt:`${passes.length} passes completos avançam ${n(forwardGain)} m rumo ao gol, somando x final menos x inicial. Conduções excluídas.`}[language]||''),equation:passes.length?passes.map(e=>`(${e.endPosition[0].toFixed(2)} − ${e.start[0].toFixed(2)})`).join(' + ')+` = ${forwardGain.toFixed(2)} m`:c.noPass,evidence_ids:passes.map(e=>e.id)},
 {id:'tempo',label:c.tempo,value:interval===null?'—':n(interval)+' s',text:interval===null?c.noShot:({en:`${n(interval)} seconds from the completed regain to shot release, with ${passes.length} completed passes in between. This measures one attack, not a team average.`,es:`${n(interval)} segundos desde la recuperación hasta iniciar el disparo, con ${passes.length} pases completos. Mide un ataque, no el promedio del equipo.`,pt:`${n(interval)} segundos da recuperação ao início do chute, com ${passes.length} passes completos. Mede um ataque, não a média da equipe.`}[language]||''),equation:interval===null?c.noShot:`${shot.t.toFixed(1)} s − ${regain.end.toFixed(1)} s = ${interval.toFixed(1)} s`,evidence_ids:regain&&shot?[regain.id,shot.id]:[]},
 {id:'pressure',label:c.gap,value:pressure?n(pressure.from)+' → '+n(pressure.to)+' m':'—',text:pressure?({en:`The gap closes by ${n(pressure.closed)} m while the receiver has the ball. Less space can limit decision time; this gap alone cannot establish a forced mistake.`,es:`La distancia se reduce ${n(pressure.closed)} m mientras el receptor tiene el balón. Menos espacio puede limitar el tiempo para decidir; esta distancia no prueba un error forzado.`,pt:`A distância diminui ${n(pressure.closed)} m enquanto o receptor está com a bola. Menos espaço pode limitar o tempo para decidir; essa distância não prova um erro forçado.`}[language]||''):c.waiting,equation:pressure?`√((x₂ − x₁)² + (y₂ − y₁)²); ${pressure.from.toFixed(2)} − ${pressure.to.toFixed(2)} = ${pressure.closed.toFixed(2)} m`:c.waiting,evidence_ids:pressure?[record.id]:[]}];
 const schedule=s.id==='press'?[[6,'pressure'],[10,'regain'],[23,'release'],[29,'finish']]:s.id==='counter'?[[7,'regain'],[12,'release'],[22,'release'],[28,'finish']]:[[5,'release'],[13,'release'],[26,'release'],[31,'finish']];
 const chapters=schedule.map(([at,kind],i)=>({at,kind,label:c[kind],reached:at<=t,index:i,clock:clock(s,at)}));
 const focus=interval!==null?calculations[1]:passes.length?calculations[0]:pressure?calculations[2]:calculations[0];
 const summary=shot?({en:`${shot.outcome==='goal'?'Goal recorded.':'Shot saved.'} ${interval!==null?`${n(interval)} seconds from regain to shot. `:''}${passes.length} completed passes supplied ${n(forwardGain||0)} m of forward passing gain. ${s.id==='press'?c.cause:''}`,es:`${shot.outcome==='goal'?'Gol registrado.':'Disparo detenido.'} ${interval!==null?`${n(interval)} segundos desde recuperar hasta disparar. `:''}${passes.length} pases completos avanzaron ${n(forwardGain||0)} m. ${s.id==='press'?c.cause:''}`,pt:`${shot.outcome==='goal'?'Gol registrado.':'Chute defendido.'} ${interval!==null?`${n(interval)} segundos da recuperação ao chute. `:''}${passes.length} passes completos avançaram ${n(forwardGain||0)} m. ${s.id==='press'?c.cause:''}`}[language]):focus.text;
 return {cutoff:t,record,seen,regain,passes,shot,forwardGain,interval,elapsed,pressure,calculations,focus,chapters,summary,words:c};
}

export function playEditorial(a,language='en'){
 const c=a.words,ids=a.seen.map(e=>e.id),math=a.focus;
 const beforeChance={en:'Use the regain as the starting point. The next question is whether a forward receiver becomes available.',es:'Toma la recuperación como inicio. La siguiente pregunta es si aparece un receptor hacia delante.',pt:'Use a recuperação como início. A próxima pergunta é se aparece um receptor à frente.'};
 const firstPass={en:'The first forward connection is complete. Follow the next receiver to see whether this becomes a chance.',es:'La primera conexión hacia delante está completa. Sigue al próximo receptor para ver si se convierte en ocasión.',pt:'A primeira conexão à frente está completa. Siga o próximo receptor para ver se vira uma chance.'};
 return {
  analyst:{summary:a.passes.length>1?c.scout:a.passes.length?firstPass[language]:c.early,evidence_ids:a.passes.length?a.passes.map(e=>e.id):a.pressure?[a.record.id]:ids},
  guide:{summary:c.definition+' '+c.question},
  math:{summary:math.text,working:math.equation,metric_value:math.value,metric_title:math.label,evidence_ids:math.evidence_ids},
  reviewer:{summary:c.cause,target_claim:({en:'The pressure forced the interception.',es:'La presión provocó la intercepción.',pt:'A pressão causou a interceptação.'})[language]},
  presenter:{summary:a.shot?c.end:a.passes.length>1?c.host:beforeChance[language],replay_cue:(a.passes.length?{en:'Replay the regain, then follow the first forward receiver.',es:'Repite la recuperación y sigue al primer receptor hacia delante.',pt:'Reveja a recuperação e siga o primeiro receptor à frente.'}:{en:'Replay the intercepted pass and the receiver who wins it.',es:'Repite el pase interceptado y el receptor que lo gana.',pt:'Reveja o passe interceptado e o receptor que ganha a bola.'})[language]}
 };
}
